/* ─── Ciblage loc / req ─── */
const LOC_COMPAT = {"#loc_cible":["#req_cible","#req_global"],"#loc_point":["#req_point","#req_global"],"#loc_soi":["#req_soi","#req_global"],"#loc_global":["#req_cible","#req_point","#req_soi","#req_global"]};

/* ─── Utilitaires ─── */
function getCompatEffects(trigger){
  if(!trigger)return GD_EFFECTS;
  const valid=LOC_COMPAT[trigger.loc]||[];
  return GD_EFFECTS.filter(e=>valid.includes(e.req));
}
function getCompatTriggers(effect){
  if(!effect)return GD_TRIGGERS;
  const vl=Object.entries(LOC_COMPAT).filter(([,r])=>r.includes(effect.req)).map(([l])=>l);
  return GD_TRIGGERS.filter(t=>vl.includes(t.loc));
}
function getRarityOrder(r){return{Commun:0,Rare:1,'Épique':2,'Légendaire':3}[r]??0;}
function rarityColor(r){return{Commun:'#6DB33F',Rare:'var(--bleu)','Épique':'#b08aff','Légendaire':'var(--or)'}[r]||'#888';}
function detectSynergies(allTags){
  return GD_ARCHETYPES.map(a=>{
    const n=a.tags.filter(t=>allTags.includes(t)).length;
    if(n>=5)return{a,tier:3};if(n>=3)return{a,tier:2};if(n>=2)return{a,tier:1};return null;
  }).filter(Boolean).sort((a,b)=>b.tier-a.tier);
}
